import fs from'node:fs';import assert from'node:assert/strict';import * as THREE from'../source/registration-vendor/three.module.js';import{createCommon}from'../create-common.mjs';import{defaultState}from'../src/State.mjs';import{commonSnapshot,exportCommon}from'../src/CommonExports.mjs';import{mixedState}from'../qa/mixed-states.mjs';
const m=createCommon({headDriver:true}),dir=new URL('../research/export-cases/',import.meta.url);fs.mkdirSync(dir,{recursive:true});const records=[];
function decodeGLB(buffer){const d=new DataView(buffer),u=new Uint8Array(buffer);assert.equal(d.getUint32(0,true),0x46546c67);assert.equal(d.getUint32(4,true),2);assert.equal(d.getUint32(8,true),buffer.byteLength);const len=d.getUint32(12,true),json=JSON.parse(new TextDecoder().decode(u.subarray(20,20+len))),bin=20+len+8;const read=i=>{const a=json.accessors[i],v=json.bufferViews[a.bufferView],T={5126:Float32Array,5123:Uint16Array,5125:Uint32Array}[a.componentType],n={SCALAR:1,VEC3:3,VEC4:4,MAT4:16}[a.type];return new T(buffer,bin+(v.byteOffset||0)+(a.byteOffset||0),a.count*n);};return{json,read};}
for(const[name,s]of[['neutral',defaultState()],['anny-mixed',mixedState({rig:'anny',headRig:'body',headShape:'anny',expression:'anny',gaze:'rig'},m.mhrMeta)],['mhr-mixed',mixedState({rig:'mhr',headRig:'gnm',headShape:'mhr',expression:'mhr',gaze:'expression'},m.mhrMeta)]]){
 m.compute(s);const snap=commonSnapshot(m),before=m.positions.slice();const files={};for(const kind of['obj','glb','usda','snapshot']){const out=exportCommon(m,kind),file=name+'.'+(kind==='snapshot'?'json':kind);fs.writeFileSync(new URL(file,dir),typeof out.data==='string'?out.data:new Uint8Array(out.data));files[kind]=file;}assert.deepEqual(m.positions,before);
 const{json,read}=decodeGLB(exportCommon(m,'glb').data),primitive=json.meshes[0].primitives[0],positions=read(primitive.attributes.POSITION),faces=read(primitive.indices),indices=read(primitive.attributes.JOINTS_0),weights=read(primitive.attributes.WEIGHTS_0),inverse=read(json.skins[0].inverseBindMatrices);assert.deepEqual(positions,snap.positions);assert.deepEqual(faces,snap.faces);
 const world=[],visit=i=>{if(world[i])return world[i];const local=new THREE.Matrix4().fromArray(json.nodes[i].matrix||new THREE.Matrix4().toArray());const parent=json.nodes.findIndex(n=>n.children?.includes(i));world[i]=parent<0?local:visit(parent).clone().multiply(local);return world[i];};json.skins[0].joints.forEach(visit);let max=0;
 for(let v=0;v<positions.length/3;v++){const p=new THREE.Vector3().fromArray(positions,v*3),q=new THREE.Vector3();for(let k=0;k<4;k++){const j=indices[v*4+k],w=weights[v*4+k];if(!w)continue;const M=world[json.skins[0].joints[j]].clone().multiply(new THREE.Matrix4().fromArray(inverse,j*16));q.addScaledVector(p.clone().applyMatrix4(M),w);}max=Math.max(max,q.distanceTo(p));}assert(max<2e-6,'Reimported GLB snapshot double-deforms: '+max);
 const raw=fs.readFileSync(new URL(files.obj,dir),'utf8'),obj=Float32Array.from(raw.split('\n').filter(x=>x.startsWith('v ')).flatMap(x=>x.slice(2).split(' ').map(Number)));assert.deepEqual(obj,snap.positions);
 const archive=JSON.parse(fs.readFileSync(new URL(files.snapshot,dir),'utf8')).archive;m.compute(defaultState());m.restore(archive);assert.deepEqual(m.positions,before);records.push({name,files,vertices:snap.positions.length/3,bodyJoints:snap.bodyJointCount,derivedHeadJoints:snap.derivedHeadJointCount,glbSkinBindRoundTripMaxMetres:max,weightReduction:snap.weightReduction,archiveExact:true});
}
fs.writeFileSync(new URL('manifest.json',dir),JSON.stringify({records,fingerprint:m.adapterFingerprint,scope:'Current posed snapshot only; later native model animation needs original adapters and correctives'},null,2));console.log({passed:true,exports:records});
